'use strict';
// Actual staged Apps Script source; actual hosted ZIP/metadata/live HTTP responses.
// Node adapters supply Google blob/digest primitives without deploying Apps Script.
const fs=require('node:fs'),vm=require('node:vm'),crypto=require('node:crypto'),cp=require('node:child_process'),assert=require('node:assert/strict');
const token=process.env.GH_READ_TOKEN,sha=process.env.GITHUB_SHA,run=process.env.GITHUB_RUN_ID,repo=process.env.GITHUB_REPOSITORY,api='https://api.github.com/repos/'+repo;
assert(repo==='ChasingMajors/chasing-majors-app');assert(process.env.GITHUB_REF==='refs/heads/probe/compressed-release-2026-10-30');
async function github(p){const r=await fetch(api+p,{headers:{Authorization:'Bearer '+token,Accept:'application/vnd.github+json','User-Agent':'CM-non-production-artifact-probe'},redirect:'manual',signal:AbortSignal.timeout(30000)});if(r.status!==200)throw Error('GitHub metadata HTTP '+r.status);return r.json();}
const blob=bytes=>({getBytes:()=>Array.from(bytes),getDataAsString:()=>Buffer.from(bytes).toString('utf8')});
(async()=>{
 let artifact;for(let n=0;n<5;n++){const j=await github('/actions/runs/'+run+'/artifacts?per_page=10');artifact=j.artifacts.find(a=>a.name==='content-release-manifest'&&!a.expired&&a.workflow_run?.head_sha===sha);if(artifact)break;await new Promise(r=>setTimeout(r,3000));}assert(artifact,'Actual SHA-bound manifest artifact missing');
 const zipUrl=api+'/actions/artifacts/'+artifact.id+'/zip',first=await fetch(zipUrl,{headers:{Authorization:'Bearer '+token,Accept:'application/vnd.github+json'},redirect:'manual',signal:AbortSignal.timeout(30000)}),responses=new Map();let archive;
 if(first.status===302){const location=first.headers.get('location');assert(/^https:\/\/[a-zA-Z0-9.-]+\.(?:blob\.core\.windows\.net|actions\.githubusercontent\.com)\//.test(location),'Unexpected signed host');responses.set(zipUrl,{code:302,headers:{Location:location}});const r=await fetch(location,{redirect:'manual',signal:AbortSignal.timeout(30000)});assert.equal(r.status,200);archive=Buffer.from(await r.arrayBuffer());responses.set(location,{code:r.status,bytes:archive});}
 else{assert.equal(first.status,200);archive=Buffer.from(await first.arrayBuffer());responses.set(zipUrl,{code:200,bytes:archive});}
 const liveUrl='https://app.chasingmajors.com/data/publish-release.json',liveResponse=await fetch(liveUrl+'?probe='+run,{cache:'no-store',signal:AbortSignal.timeout(20000)});assert([200,404].includes(liveResponse.status),'Unexpected live service failure');responses.set(liveUrl,{code:liveResponse.status,bytes:Buffer.from(await liveResponse.arrayBuffer())});
 let signedRequests=0;const ctx={console,Date,JSON,PropertiesService:{getScriptProperties:()=>({getProperty:key=>{assert.equal(key,'CM_PUBLISH_GITHUB_READ_TOKEN');return token;}})},Utilities:{DigestAlgorithm:{SHA_256:'SHA256'},Charset:{UTF_8:'UTF8'},computeDigest:(_,v)=>Array.from(crypto.createHash('sha256').update(typeof v==='string'?v:Buffer.from(v)).digest()),unzip:b=>{
  const py='import sys,io,zipfile,json,base64\nz=zipfile.ZipFile(io.BytesIO(sys.stdin.buffer.read()))\nassert len(z.infolist())==1\nf=z.infolist()[0]\nassert f.file_size<=3*1024*1024\nprint(json.dumps({"name":f.filename,"body":base64.b64encode(z.read(f)).decode()}))';
  const r=cp.spawnSync('python3',['-c',py],{input:Buffer.from(b.getBytes()),maxBuffer:5*1024*1024});assert.equal(r.status,0,'Real ZIP decode failed');const j=JSON.parse(r.stdout),v=Buffer.from(j.body,'base64');return [{...blob(v),getName:()=>j.name}];
 }},UrlFetchApp:{fetch:(url,options)=>{const key=url.startsWith(liveUrl+'?')?liveUrl:url,r=responses.get(key);assert(r,'Unexpected monitor URL');if(!url.startsWith(api)){assert(!options.headers?.Authorization,'Credential forwarded to storage/live host');if(key!==liveUrl)signedRequests++;}return {getResponseCode:()=>r.code,getAllHeaders:()=>r.headers||{},getBlob:()=>blob(r.bytes),getContentText:()=>Buffer.from(r.bytes||'').toString('utf8')};}}};
 vm.createContext(ctx);const source=fs.readFileSync('.github/probes/PublishMonitor.gs','utf8');vm.runInContext(source,ctx);const job={submitted_sha:sha,release_sha:sha,artifact_mode:true,artifact_manifest_id:artifact.id,artifact_manifest_digest:artifact.digest,artifact_manifest_size:artifact.size_in_bytes,code:'probe-not-published',kind:'checklist',sport:'baseball'};
 const verified=ctx.pubmonArtifactManifest_(job);assert.equal(verified.manifest.release_sha,sha);let held=false;try{held=ctx.pubmonLiveArtifact_(job).ok===false;}catch(e){if(liveResponse.status!==404)throw e;held=/unavailable/.test(e.message);}assert(held,'Unpublished probe incorrectly verified live');
 console.log(JSON.stringify({probe_only:true,run_id:Number(run),source_sha:sha,monitor_source_sha256:crypto.createHash('sha256').update(source).digest('hex'),artifact_id:artifact.id,artifact_digest:artifact.digest,archive_bytes:archive.length,manifest_source_sha:verified.manifest.release_sha,archive_digest_verified:true,real_zip_decoded:true,artifact_size_guard_checked:true,live_manifest_http:liveResponse.status,unpublished_release_held:true,live_verified:false,signed_requests_without_credentials:signedRequests,positive_pages_deploy:'NOT RUN: owner approval required',d1_reads:0,d1_writes:0}));
})().catch(e=>{console.error(e.message);process.exitCode=1;});
